import re

from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone

__author__ = 'Sylwester Golonka'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'sylwester.golonka@nokia.com'


class RebootUboot(GenericUnixCommand):
    """Rebootuboot command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, expected_prompt=r"uboot#"):
        """
        Rebootuboot command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after entering Argon
        :param newline_chars:
        """
        super(RebootUboot, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.expected_prompt = CommandTextualGeneric._calculate_prompt(expected_prompt)
        self._auto_boot_sent = False
        self._uboot_menu_sent = False
        self.timeout = 150

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "reboot"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._parse_stop_autoboot(line)
            self._parse_uboot_menu(line)
            self._parse_expected_prompt(line)
        except ParsingDone:
            pass

    _re_stop_autoboot = re.compile(r"Hit 'c' key to stop autoboot")

    def _parse_stop_autoboot(self, line):
        """
        Send the character 'c' to stop autoboot when parse line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(RebootUboot._re_stop_autoboot, line):
            if not self._auto_boot_sent:
                self._auto_boot_sent = True
                self.connection.sendline("c")
            raise ParsingDone()

    _re_uboot_menu = re.compile(r"U-Boot menu, press key for option:")

    def _parse_uboot_menu(self, line):
        """
        Send the character 'a' to choose uboot from the menu.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(RebootUboot._re_uboot_menu, line):
            if not self._uboot_menu_sent:
                self._uboot_menu_sent = True
                self.connection.sendline("a")
            raise ParsingDone()

    def _parse_expected_prompt(self, line):
        """
        Set result if parse prompt in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(self.expected_prompt, line):
            self.set_result({})
        raise ParsingDone()


